"OLAYLAR_ORTACAG_ORTADOGU:1250-02-01:0":{"b": ["Turan-Shah was proclaimed sultan in the camp at Mansura.", "68cea03d"], "d": ["Turan-Shah was proclaimed sultan in the camp at Mansura.", "68cea03d"]},
"OLAYLAR_ORTACAG_ORTADOGU:1250-04-05:0":{"b": ["After the Mamluks killed Turan Shah, at the invitation of the emirs of Damascus an-Nasir Yusuf took Damascus without a fight (648/1250); the Aleppo branch also ruled Damascus.", "3f4f40d7"], "d": ["After the Mamluks killed Turan Shah, at the invitation of the emirs of Damascus an-Nasir Yusuf took Damascus without a fight (648/1250); the Aleppo branch also ruled Damascus.", "3f4f40d7"]},
"OLAYLAR_ORTACAG_ORTADOGU:1250-04-07:0":{"b": ["Mansura: the Muslims decisively defeated the Crusader army of Louis IX", "8d1db119"], "d": ["In the battles that lasted from the beginning of March to 7 April 1250, the Crusaders were decisively defeated; the king and his entourage were to be released in return for the restitution of Damietta and a heavy ransom.", "4c176422"]},
"OLAYLAR_ORTACAG_ORTADOGU:1250-05-07:0":{"b": ["Damietta was returned to the Muslims", "f7070829"], "d": ["In return for the release of the king, Damietta was surrendered to the Muslims on 7 May 1250.", "16c1ec7a"]},
"OLAYLAR_ORTACAG_ORTADOGU:1251-02-03:0":{"b": ["Al-Nasir Yusuf defeated the Mamluk army at the Battle of Abbasa and the khutba was read in his name in Cairo; in 1253 peace was made through an envoy of the caliph.", "1e4046b9"], "d": ["Al-Nasir Yusuf defeated the Mamluk army at the Battle of Abbasa and the khutba was read in his name in Cairo; in 1253 peace was made through an envoy of the caliph.", "1e4046b9"]},
"OLAYLAR_ORTACAG_ORTADOGU:1258-01-01:0":{"b": ["Hulagu arrived before Baghdad in January 1258 and besieged the city.", "d47bf386"], "d": ["Hulagu arrived before Baghdad in January 1258 and besieged the city.", "d47bf386"]},
"OLAYLAR_ORTACAG_ORTADOGU:1260-01-01:0":{"b": ["Hulagu captured Aleppo; the Aleppo Ayyubid branch came to an end", "f9f61122"], "d": ["Hulagu captured Aleppo; the Aleppo Ayyubid branch came to an end", "f9f61122"]},
"OLAYLAR_ORTACAG_ORTADOGU:1281-01-01:0":{"b": ["The Mamluk Sultan Qalawun made an eleven-year truce with the knights of Marqab, the Count of Tripoli, the Templars and Acre (end of 679/1281; month indicated, no day).", "39e0272e"], "d": ["The Mamluk Sultan Qalawun made an eleven-year truce with the knights of Marqab, the Count of Tripoli, the Templars and Acre (end of 679/1281; month indicated, no day).", "39e0272e"]},
"OLAYLAR_ORTACAG_ORTADOGU:1283-04-08:0":{"b": ["Al-Malik al-Kamil Muhammad III enters the list of rulers (682/1283, beginning of the Hijri year).", "749a9cca"], "d": ["Al-Malik al-Kamil Muhammad III enters the list of rulers (682/1283, beginning of the Hijri year).", "749a9cca"]},
"OLAYLAR_ORTACAG_ORTADOGU:1285-01-01:0":{"b": ["Qalawun took the fortress of Marqab (Margat) from the Hospitallers and eliminated this Crusader force; the last great Crusader stronghold in the immediate vicinity of the County of Tripoli fell (684/1285).", "722b884f"], "d": ["Qalawun took the fortress of Marqab (Margat) from the Hospitallers and eliminated this Crusader force; the last great Crusader stronghold in the immediate vicinity of the County of Tripoli fell (684/1285).", "722b884f"]},
"OLAYLAR_ORTACAG_ORTADOGU:1287-01-01:0":{"b": ["Count Bohemond VII died; the succession dispute between his sister Lucia and the city commune, supported by the Genoese, weakened the county and gave Qalawun his opportunity.", "e68819ba"], "d": ["Count Bohemond VII died; the succession dispute between his sister Lucia and the city commune, supported by the Genoese, weakened the county and gave Qalawun his opportunity.", "e68819ba"]},
"OLAYLAR_ORTACAG_ORTADOGU:1289-04-26:0":{"b": ["Qalawun conquered Tripoli; the County of Tripoli came to an end", "2c912cc3"], "d": ["Qalawun conquered Tripoli; the County of Tripoli came to an end", "2c912cc3"]},
"OLAYLAR_ORTACAG_ORTADOGU:1291-07-01:0":{"b": ["Sidon passed to the Mamluks (the Templar knights withdrew)", "2339a488"], "d": ["On the conquest of Acre (690/1291), the Templar knights who left it took refuge in Sidon; the city fell into the hands of the Mamluks in Rajab 690 / July 1291, and its walls were demolished.", "4c9103e0"]},
"OLAYLAR_ORTACAG_ORTADOGU:1291-07-14:0":{"b": ["The Mamluks took Tyre; the Crusader coastal state (the Kingdom of Jerusalem) came to an end", "f52aa213"], "d": ["The Mamluks took Tyre; the Crusader coastal state (the Kingdom of Jerusalem) came to an end", "f52aa213"]},
"OLAYLAR_ORTACAG_ORTADOGU:1310-10-03:0":{"b": ["The historian Abu'l-Fida was appointed deputy governor of Hama by the Mamluk sultan (8 Jumada al-Ula 710).", "8dbf5f8f"], "d": ["The historian Abu'l-Fida was appointed deputy governor of Hama by the Mamluk sultan (8 Jumada al-Ula 710).", "8dbf5f8f"]},
"OLAYLAR_ORTACAG_ORTADOGU:1312-08-30:0":{"b": ["Abu'l-Fida became prince of Hama with the title 'al-Malik al-Salih' (25 Rabi' al-Akhir 712).", "e03a1512"], "d": ["Abu'l-Fida became prince of Hama with the title 'al-Malik al-Salih' (25 Rabi' al-Akhir 712).", "e03a1512"]},
"OLAYLAR_ORTACAG_ORTADOGU:1320-02-28:0":{"b": ["Abu'l-Fida assumed the title of sultan (17 Muharram 720).", "8ae22f37"], "d": ["Abu'l-Fida assumed the title of sultan (17 Muharram 720).", "8ae22f37"]},
